const REAL_QA_RUN='live-qa-bounded-20261016',REAL_QA_RELATIVE=`.local/exports/multilingual-001/p1-v1/${REAL_QA_RUN}`,REAL_QA_RECEIPT=`.local/test-outputs/multilingual-001/p1-v1/${REAL_QA_RUN}/export-result.json`;
const qaFs=await import('node:fs'),qaPath=await import('node:path'),{fileURLToPath:qaFilePath}=await import('node:url'),{createHash:qaHash}=await import('node:crypto');
const QA_CMS_ROOT=qaPath.resolve(qaFilePath(new URL('../',import.meta.url)));
const realQaAvailable=qaFs.existsSync(qaPath.join(QA_CMS_ROOT,REAL_QA_RELATIVE))&&qaFs.existsSync(qaPath.join(QA_CMS_ROOT,REAL_QA_RECEIPT));
function readBoundedQaFile(relative,cap){
 const absolute=qaPath.resolve(QA_CMS_ROOT,relative);if(!absolute.startsWith(QA_CMS_ROOT+qaPath.sep))throw Error('QA fixture escaped workspace');
 let current=QA_CMS_ROOT;for(const part of qaPath.relative(QA_CMS_ROOT,absolute).split(qaPath.sep)){current=qaPath.join(current,part);if(qaFs.lstatSync(current).isSymbolicLink()||qaFs.realpathSync(current)!==current)throw Error('QA fixture symlink rejected');}
 const stat=qaFs.lstatSync(absolute);if(!stat.isFile()||stat.nlink!==1||stat.size<1||stat.size>cap)throw Error('QA fixture type/size rejected');const bytes=qaFs.readFileSync(absolute);if(bytes.length!==stat.size)throw Error('QA fixture changed during read');return bytes;
}

