// Explicitly opt-in real UI verification. The Coordinator alone writes this
// nonsecret request. No application, auth provider or guard is replaced.
const REAL_UI_REQUEST='.local/test-outputs/multilingual-001/p1-v2/real-ui-request.json';
const realUiRequested=qaFs.existsSync(qaPath.join(QA_CMS_ROOT,REAL_UI_REQUEST));
// Worker options belong to the file suite; absent marker retains headless smoke.
test.use({headless:!realUiRequested,trace:'off',video:'off',screenshot:'off'});
const {canonicalJson:realUiCanonical}=await import('../contracts/draft.mjs');
const {localizedHeroReadSchema:realUiReadSchema,localizedHeroReceiptSchema:realUiReceiptSchema}=await import('../contracts/hero-localization-records.mjs');
const {localizedHeroSaveSchema:realUiSaveSchema,localizedHeroContentSchema:realUiContentSchema}=await import('../contracts/hero-localization.mjs');
const realUiDigest=value=>qaHash('sha256').update(typeof value==='string'?value:realUiCanonical(value)).digest('hex');
function exactRealUiKeys(value,keys){if(!value||Array.isArray(value)||typeof value!=='object'||Object.keys(value).sort().join('|')!==[...keys].sort().join('|'))throw Error('REAL_UI invalid request shape');}
function readRealUiRequest(){
 const markerFile=qaPath.join(QA_CMS_ROOT,REAL_UI_REQUEST);if((qaFs.lstatSync(markerFile).mode&0o777)!==0o600)throw Error('REAL_UI marker must be private0600');
 const marker=JSON.parse(readBoundedQaFile(REAL_UI_REQUEST,16384));exactRealUiKeys(marker,['mode','runId','projectId','origin','baseRevision','expectedDrafts','bundlePath','expiresAt','maxSuccessfulWrites']);
 if(marker.mode!=='REAL_AUTHENTICATED_P1_V2'||marker.projectId!=='demo-pinky-lamb-cms'||marker.origin!=='http://127.0.0.1:5173'||marker.baseRevision!==0||marker.maxSuccessfulWrites!==8||!/^[A-Za-z0-9][A-Za-z0-9_-]{0,99}$/.test(marker.runId??''))throw Error('REAL_UI wrong project/mode/budget');
 const expiry=Date.parse(marker.expiresAt);if(!Number.isFinite(expiry)||new Date(expiry).toISOString()!==marker.expiresAt||expiry<=Date.now()||expiry-Date.now()>24*60*60*1000)throw Error('REAL_UI expiry must be future ISO UTC within24hours');
 exactRealUiKeys(marker.expectedDrafts,['en','vi','ja']);for(const locale of ['en','vi','ja']){const expected=marker.expectedDrafts[locale];exactRealUiKeys(expected,['revision','contentHash']);if(!Number.isSafeInteger(expected.revision)||expected.revision<1||!/^[a-f0-9]{64}$/.test(expected.contentHash??''))throw Error('REAL_UI expected draft identity is invalid');}
 if(typeof marker.bundlePath!=='string'||!/^\.local\/(?:test-outputs|cache)\/multilingual-001\/p1-v2\/[A-Za-z0-9_./-]+\.json$/.test(marker.bundlePath)||marker.bundlePath.split('/').some(part=>!part||part==='.'||part==='..'))throw Error('REAL_UI unsafe original bundle path');
 const bundle=JSON.parse(readBoundedQaFile(marker.bundlePath,96*1024*1024));exactRealUiKeys(bundle,['contractRevision','kind','entries']);if(bundle.contractRevision!==1||bundle.kind!=='LOCALIZED_HERO_QA_BUNDLE'||!Array.isArray(bundle.entries)||bundle.entries.length!==3)throw Error('REAL_UI invalid safe bundle');
 const entries=new Map();for(const entry of bundle.entries){exactRealUiKeys(entry,['qa','files']);const draft=entry.qa?.draft;if(!['en','vi','ja'].includes(draft?.locale)||entries.has(draft.locale)||draft.revision!==marker.expectedDrafts[draft.locale]?.revision||draft.baseRevision!==0||draft.contentHash!==marker.expectedDrafts[draft.locale].contentHash)throw Error('REAL_UI bundle baseline mismatch');const content=realUiContentSchema.parse(draft.content);if(realUiDigest(content)!==draft.contentHash)throw Error('REAL_UI original content digest mismatch');entries.set(draft.locale,content);}
 return {marker,original:entries.get('en'),originals:entries};
}

function createRealUiCasBarrier(timeoutMs=5000){
 let cancelled=false,timer=null,waiters=[];
 const cancel=(reason='REAL_UI CAS barrier cancelled')=>{cancelled=true;clearTimeout(timer);const pending=waiters;waiters=[];for(const waiter of pending)waiter.reject(Error(reason));};
 return {cancel,wait(){if(cancelled)return Promise.reject(Error('REAL_UI CAS barrier is closed'));return new Promise((resolve,reject)=>{waiters.push({resolve,reject});if(waiters.length===2){clearTimeout(timer);const pair=waiters;waiters=[];for(const waiter of pair)waiter.resolve();}else timer=setTimeout(()=>cancel('REAL_UI second CAS request did not arrive'),timeoutMs);});}};
}
async function drainRealUiMutations(handlers,timeoutMs=16000){
 const deadline=Date.now()+timeoutMs;
 while(handlers.size){const remaining=deadline-Date.now();if(remaining<=0)return false;let timer;const settled=await Promise.race([Promise.allSettled([...handlers]).then(()=>true),new Promise(resolve=>{timer=setTimeout(()=>resolve(false),remaining);})]);clearTimeout(timer);if(!settled)return false;}
 return true;
}
// A read-only observation timeout does not cancel an already-started browser
// evaluation. The caller stops that page's cleanup instead of issuing more work.
async function boundedRealUiObservation(action,timeoutMs=15000){
 let timer;try{return await Promise.race([Promise.resolve().then(action),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('REAL_UI read-only observation timed out')),timeoutMs);})]);}finally{clearTimeout(timer);}
}
test('controlled cleanup observation times out a stalled read and propagates ordinary failures',async()=>{
 await expect(boundedRealUiObservation(()=>new Promise(()=>{}),20)).rejects.toThrow('read-only observation timed out');
 expect(await boundedRealUiObservation(async()=>({stage:'settled'}),1000)).toEqual({stage:'settled'});
 await expect(boundedRealUiObservation(async()=>{throw Error('synthetic read failure');},1000)).rejects.toThrow('synthetic read failure');
});
// Controlled harness regression: this exercises the same barrier and bounded
// drain used by real routing, without any browser, session or network request.
test('controlled CAS cleanup cancels a held write instead of delivering it',async()=>{
 const barrier=createRealUiCasBarrier(),handlers=new Set();let deliveries=0;
 const operation=(async()=>{await barrier.wait();deliveries++;})();handlers.add(operation);operation.catch(()=>{}).finally(()=>handlers.delete(operation));barrier.cancel('REAL_UI deterministic cleanup');
 expect(await drainRealUiMutations(handlers,1000)).toBe(true);expect(deliveries).toBe(0);await expect(barrier.wait()).rejects.toThrow('closed');
 let finish;const pending=new Promise(resolve=>{finish=resolve;});handlers.add(pending);expect(await drainRealUiMutations(handlers,20)).toBe(false);finish();handlers.delete(pending);
});

